{
  "meta": {
    "title": "mail",
    "surface": "mail",
    "status": "draft",
    "owner": "platform",
    "date": "2026-10-06",
    "purpose": "The statement the workshop grows from. Details belong to the workshop and the spec agents.",
    "sources": [
      {
        "ref": "~/.claude/intent/mail-words.md",
        "kind": "doc",
        "note": "The operator's words, verbatim"
      }
    ]
  },
  "what_it_is": "Mail is a complete, open source email service for everyone, from individuals and small teams to businesses and the brands on platform. It can replace the hosted email people pay a lot for every month, all the way up to what businesses need. It matters because email still carries much of the support and communication between people and organizations.",
  "current_state": {
    "real": [],
    "cut_or_broken": [
      {
        "text": "What mail claims to do today is not true. It was reported finished when it was not, so nobody can rely on any part of it as working.",
        "why": "The previous handover reported mail complete when nothing was finished."
      }
    ],
    "known_gaps": [
      {
        "text": "Nobody knows yet how mail reliably gets each message to the right place.",
        "when_it_matters": "Before anyone relies on mail to receive their email."
      },
      {
        "text": "The hosting mail runs on gives senders no way to see what happened to their mail.",
        "when_it_matters": "As soon as anyone sends through mail and needs to know whether it arrived."
      },
      {
        "text": "Mail has no place of its own to read and write mail. People reach their mail through the mail apps they already use.",
        "when_it_matters": "Much later, by the operator's choice. Reading mail in existing apps is needed from day one."
      }
    ]
  },
  "direction": {
    "becoming": "Mail is becoming a service people can trust, because everything it claims has been shown to work. It gives the same mailbox experience they already know, and senders can see what happened to everything they send.",
    "proposals": [
      {
        "text": "Nothing in mail counts as working until it has been shown to work.",
        "status": "settled",
        "needs_pressure_test": false
      },
      {
        "text": "Whoever runs mail can choose and switch who sends and receives the mail, without the people using it noticing.",
        "status": "settled",
        "needs_pressure_test": false
      },
      {
        "text": "Senders know what happened to what they sent, at least as well as the best sending services tell them today.",
        "status": "settled",
        "needs_pressure_test": false
      },
      {
        "text": "A work inbox feels just like the mailbox people already use, and businesses get sign-in with their own identity and rules for how long mail is kept.",
        "status": "settled",
        "needs_pressure_test": false
      }
    ]
  },
  "boundaries": [
    {
      "owner": "messages",
      "owns": "Collecting subscription requests (what platform-newsletter was going to be), and later phone, text and video"
    },
    {
      "owner": "mail",
      "owns": "Email: sending, receiving, getting each message to the right place, tracking what happened to sent mail, and work inboxes"
    }
  ],
  "actors": [
    {
      "name": "Person using a mailbox (individual or employee)",
      "type": "end-user",
      "touches": "Their inbox, read from the mail apps they already use",
      "stakes": "Whether their mail arrives, and whether using it feels like the mailbox they already know"
    },
    {
      "name": "Sender (support, communications, a brand on platform)",
      "type": "human",
      "touches": "Sending mail, and seeing what happened to it afterwards",
      "stakes": "Whether they can know that what they sent arrived and what happened to it"
    },
    {
      "name": "Business running work email",
      "type": "human",
      "touches": "Signing in with their own company identity, and rules for how long mail is kept",
      "stakes": "Whether mail can replace the work email provider they pay for today"
    },
    {
      "name": "Whoever runs mail",
      "type": "human",
      "touches": "Choosing who actually sends and receives the mail",
      "stakes": "Not being locked into one provider"
    },
    {
      "name": "Sending and receiving providers",
      "type": "machine",
      "touches": "Carrying mail in and out on mail's behalf",
      "stakes": "Can be swapped without the people using mail noticing"
    }
  ],
  "consumers": [
    {
      "name": "Support and communications, for anyone who uses email for them",
      "relationship": "Email is still huge for support and communications",
      "status": "not-built"
    },
    {
      "name": "Work email inboxes for businesses and teams",
      "relationship": "Need to be just like the mailbox the person already uses",
      "status": "not-built"
    }
  ],
